const destinations=document.getElementById('destinations');
if(destinations){destinations.innerHTML=['Goa','Himachal','Meghalaya','Rajasthan','North East'].map((name,i)=>`<article class="destination"><div class="landscape" role="img" aria-label="Illustrative Indian destination landscape"><span>0${i+1} / EXPLORE INDIA</span></div><p class="destination-type">HOSTED GROUP TRIP</p><h4>${name}</h4><p><b>₹7,000–₹25,000</b> · overall case band</p><p>Dates, captain and final payable amount confirmed before booking.</p>${name==='Himachal'?'<a class="trip-link" href="himachal.html#inclusions">Open trip detail →</a>':`<button type="button" data-trip="${name}">Open trip detail →</button>`}</article>`).join('');destinations.addEventListener('click',e=>{const button=e.target.closest('[data-trip]');if(button)document.getElementById('destination-message').textContent=`${button.dataset.trip}: Example detail not built — Himachal is the walkthrough destination.`;});}
const book=document.getElementById('book');if(book){book.addEventListener('click',()=>document.getElementById('review').showModal());document.getElementById('close-review').addEventListener('click',()=>document.getElementById('review').close());}
